def move_coop_guests(apps, schema_editor):
    """Нээлттэй өрөөн дэх найз (Room.guest + guest_coop) RoomFriend руу: Room.guest зөвхөн тулааны зочин болно."""
    Room = apps.get_model("game", "Room")
    RoomFriend = apps.get_model("game", "RoomFriend")
    now = timezone.now()
    for room in Room.objects.filter(status="open", guest_coop=True, guest__isnull=False):
        RoomFriend.objects.create(room=room, player_id=room.guest_id, seen=room.guest_seen or now,
                                  joined=room.guest_joined or now, confirmed=room.guest_confirmed)
        room.guest = None
        room.guest_seen = room.guest_joined = None
        room.guest_confirmed = False
        room.save(update_fields=["guest", "guest_seen", "guest_joined", "guest_confirmed"])


